  assert.equal(temp(20,20,5),20);
  assert.ok(temp(20,10,5)>10);
  assert.ok(temp(20,10,5)<20);
  assert.ok(T.assumptions.some(x=>/3-to-2|3→2|cannibal/i.test(x)));
